#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url" || true  # explorer.exe exits 1 even on success
    elif command -v cmd.exe     >/dev/null 2>&1; then cmd.exe /c start "" "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────

# Ativa o canais-04 (primeiro ciclo real por E-mail) no projeto Supabase de pré-produção: aplica as três
# migrations do dia 2026-09-26, confere os segredos, publica as Edge Functions e acrescenta os eventos de
# e-mail ao Webhook Endpoint já cadastrado na Unipile, sem criar outro nem trocar o segredo. Nenhuma chave
# é gravada em disco por este wizard.
#
# Precisa da Supabase CLI (ou do Node.js, para usá-la por npx) e de curl; jq ou python3 ajudam a ler o
# JSON da Unipile (sem eles, o passo do webhook mostra o caminho pelo painel).
#
# Rode num terminal interativo (de qualquer pasta do repositório):
#   scripts/wizard-canais-04.sh
# Para outro projeto: SUPABASE_REF=<ref> scripts/wizard-canais-04.sh
# No Windows, rode pelo Git Bash: o Windows PowerShell não executa .sh.

TOTAL_STAGES=6

RAIZ="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$RAIZ"
SUPABASE_REF="${SUPABASE_REF:-ycbdilsmydvzezhlymty}"
PAINEL="https://supabase.com/dashboard/project/$SUPABASE_REF"
FUNCOES_URL="https://$SUPABASE_REF.supabase.co/functions/v1"
WEBHOOK_URL="$FUNCOES_URL/unipile-account-status"
UNIPILE_API_BASE="https://api.unipile.com"
UNIPILE_PAINEL="https://dashboardv2.unipile.com"
MIGRATIONS=(20260926163645 20260926173314 20260926180204)
# Só e-mail. O canais-06 (WhatsApp) também precisa que o Webhook Endpoint compartilhado receba `message.new`
# (mais `message.receipt.read`, para os recibos de leitura), mas isso muda o endpoint de todos e PRECISA DO OK DO NAN:
# este wizard não acrescenta esses eventos. Só está documentado aqui; ver supabase/functions/README.md.
EVENTOS_NOVOS=(email.new email.new.bounce)
SEGREDOS=(UNIPILE_API_KEY UNIPILE_WEBHOOK_SECRET APP_ORIGIN)

[[ -t 0 ]] || { printf 'Rode este wizard num terminal interativo.\n' >&2; exit 1; }

# ler_secreto PROMPT lê um valor sem ecoar na tela e sem gravar em disco.
ler_secreto() {
  local valor
  printf '  %s%s%s ' "$BOLD" "$1" "$RESET" >&2
  read -rs valor
  printf '\n' >&2
  printf '%s' "$valor"
}

# limpar TEXTO tira espaços, quebras de linha e marcadores de colagem que o terminal possa incluir.
limpar() {
  local v="$1"
  v=${v//$'\e[200~'/}
  v=${v//$'\e[201~'/}
  printf '%s' "$v" | tr -d '[:space:][:cntrl:]'
}

# rodar CMD... mostra o comando, roda e devolve o status, sem abortar o wizard.
rodar() {
  printf '  %s$%s %s\n' "$DIM" "$RESET" "$*"
  "$@"
}

# endpoint_por_url ARQUIVO imprime duas linhas (id e eventos) do endpoint com a URL do webhook, lendo o
# JSON da Unipile com jq ou python3. Sem os dois, devolve falha e o wizard segue pelo painel.
endpoint_por_url() {
  local arquivo="$1"
  if command -v jq >/dev/null 2>&1; then
    jq -r --arg url "$WEBHOOK_URL" '(.items // .) | map(select(.url == $url)) | .[0] // {} |
      (.id // ""), ((.trigger_events // []) | join(" "))' "$arquivo" 2>/dev/null
  elif command -v python3 >/dev/null 2>&1; then
    WEBHOOK_URL="$WEBHOOK_URL" python3 - "$arquivo" <<'PY' 2>/dev/null
import json, os, sys
dados = json.load(open(sys.argv[1]))
itens = dados.get('items', []) if isinstance(dados, dict) else dados
alvo = os.environ['WEBHOOK_URL']
achado = next((i for i in itens if isinstance(i, dict) and i.get('url') == alvo), {})
print(achado.get('id', ''))
print(' '.join(achado.get('trigger_events') or []))
PY
  else
    return 1
  fi
}

banner "canais-04: ativar o primeiro ciclo real por E-mail"

stage "Pré-requisitos: Supabase CLI ligada ao projeto"
say "As migrations e as Edge Functions vão pela Supabase CLI, com a sua conta do Supabase. Este wizard"
say "não pede nem guarda nenhuma chave do Supabase."
if ! command -v supabase >/dev/null 2>&1; then
  if command -v npx >/dev/null 2>&1; then
    # Sem a CLI instalada, o npx baixa o binário na primeira chamada (o pacote npm não aceita instalação global).
    supabase() { npx --yes supabase@2 "$@"; }
    note "Supabase CLI não instalada: usando 'npx supabase' (a primeira chamada baixa o binário, pode demorar)."
  else
    warn "A Supabase CLI não está instalada, e não há npx para usá-la sem instalar."
    open_url "https://supabase.com/docs/guides/local-development/cli/getting-started"
    step "Instale a CLI (Scoop no Windows, Homebrew no Mac) ou o Node.js, e rode este wizard de novo."
    exit 1
  fi
fi
note "Supabase CLI: $(supabase --version 2>/dev/null | tail -n1)"
if ! supabase projects list >/dev/null 2>&1; then
  step "Entre na sua conta do Supabase pelo navegador que a CLI vai abrir."
  rodar supabase login || { warn "Não foi possível entrar. Rode 'supabase login' à mão e volte."; exit 1; }
fi
step "Ligando este repositório ao projeto $SUPABASE_REF (a CLI pode pedir a senha do banco; Enter pula)."
if ! rodar supabase link --project-ref "$SUPABASE_REF"; then
  warn "O link com o projeto não deu certo, e as próximas etapas dependem dele."
  step "Leia o erro acima, corrija (login, permissão no projeto) e rode este wizard de novo."
  exit 1
fi
if [[ ! -f supabase/.temp/project-ref ]]; then
  warn "A CLI não gravou o projeto ligado (supabase/.temp/project-ref). Rode 'supabase link --project-ref $SUPABASE_REF' à mão e volte."
  exit 1
fi
note "Projeto ligado: $(cat supabase/.temp/project-ref)"
pause "Tecle Enter para seguir"

stage "Migrations do canais-04 no banco remoto"
say "Três migrations entram em ordem, e a versão gravada é o nome do arquivo (docs/agents/migrations.md):"
for m in "${MIGRATIONS[@]}"; do note "  $m  $(basename "$(ls supabase/migrations/${m}_*.sql 2>/dev/null | head -n1)")"; done
say ""
say "Estado atual (Local = no repositório, Remote = já aplicada no projeto):"
rodar supabase migration list --linked || warn "Não deu para listar. Confira o link com o projeto."
say ""
warn "Nada aqui apaga dados: as migrations só criam objetos e ampliam um check. Ainda assim, confira a lista."
if confirm "Aplicar as migrations pendentes no projeto $SUPABASE_REF agora?"; then
  if rodar supabase db push --linked; then
    note "Aplicadas. Conferindo de novo:"
    rodar supabase migration list --linked || true
  else
    warn "O db push falhou. Leia o erro acima; nenhuma migration parcial fica gravada."
    SKIPPED+=("Migrations: rode 'supabase db push --linked' depois de corrigir o erro")
  fi
else
  SKIPPED+=("Migrations do canais-04: 'supabase db push --linked'")
fi
pause "Tecle Enter para seguir"

stage "Segredos das Edge Functions"
say "As funções lêem UNIPILE_API_KEY, UNIPILE_WEBHOOK_SECRET e APP_ORIGIN em tempo de execução. Só os"
say "nomes são conferidos aqui; os valores ficam no painel do Supabase."
FALTANDO=()
if LISTA_SEGREDOS=$(supabase secrets list --project-ref "$SUPABASE_REF" 2>&1) && grep -q "SUPABASE_URL" <<<"$LISTA_SEGREDOS"; then
  for nome in "${SEGREDOS[@]}"; do
    if grep -qw "$nome" <<<"$LISTA_SEGREDOS"; then note "  ✓ $nome"; else warn "  falta $nome"; FALTANDO+=("$nome"); fi
  done
else
  warn "Não deu para listar os segredos pela CLI; confira os três nomes no painel, sem alterar o que já existe."
  note "${LISTA_SEGREDOS:-(sem saída)}"
  open_url "$PAINEL/functions/secrets"
  step "Role a página até a lista dos segredos existentes e confira: ${SEGREDOS[*]}."
  step "Se algum faltar mesmo, os da Unipile vêm do scripts/wizard-unipile.sh; não os invente aqui."
  pause "Tecle Enter depois de conferir"
fi
if (( ${#FALTANDO[@]} )); then
  open_url "$PAINEL/functions/secrets"
  step "Defina em Edge Functions → Secrets: ${FALTANDO[*]}."
  note "A chave de API e o segredo do webhook vêm da Unipile (scripts/wizard-unipile.sh os cadastra);"
  note "APP_ORIGIN é a origem HTTPS do app, ou http://localhost:5173 no desenvolvimento."
  pause "Tecle Enter depois de salvar"
else
  note "Os três segredos existem."
fi
pause "Tecle Enter para seguir"

stage "Publicar as Edge Functions"
say "Três funções mudaram no canais-04. O webhook vai sem verificação de JWT do gateway, porque a Unipile"
say "não manda JWT do Supabase: ele autentica cada entrega pela assinatura HMAC."
note "  sequence-step-sends           (envio do passo, exige JWT do titular)"
note "  received-email-attachments    (URL assinada do anexo, exige JWT do titular)"
note "  unipile-account-status        (webhook, --no-verify-jwt)"
if confirm "Publicar as três funções em $SUPABASE_REF agora?"; then
  FALHAS_DEPLOY=()
  rodar supabase functions deploy sequence-step-sends --project-ref "$SUPABASE_REF" || FALHAS_DEPLOY+=(sequence-step-sends)
  rodar supabase functions deploy received-email-attachments --project-ref "$SUPABASE_REF" || FALHAS_DEPLOY+=(received-email-attachments)
  rodar supabase functions deploy unipile-account-status --no-verify-jwt --project-ref "$SUPABASE_REF" || FALHAS_DEPLOY+=(unipile-account-status)
  if (( ${#FALHAS_DEPLOY[@]} )); then
    warn "Falhou: ${FALHAS_DEPLOY[*]}. Leia o erro acima e publique de novo com 'supabase functions deploy <nome> --project-ref $SUPABASE_REF'."
    SKIPPED+=("Publicar: ${FALHAS_DEPLOY[*]}")
  else
    note "As três funções estão publicadas em $FUNCOES_URL/…"
  fi
else
  SKIPPED+=("Publicar as Edge Functions sequence-step-sends, received-email-attachments e unipile-account-status (--no-verify-jwt)")
fi
pause "Tecle Enter para seguir"

stage "Webhook Endpoint da Unipile: acrescentar os eventos de e-mail"
say "O endpoint já cadastrado recebe só os 7 eventos de conta. Ele precisa ganhar email.new e"
say "email.new.bounce. É o mesmo endpoint da frente de Conexões: não crie outro nem troque o segredo."
note "O WhatsApp (canais-06) vai precisar também de message.new: precisa do OK do Nan, este wizard não o acrescenta."
say "Este wizard tenta editar por API; a chave só fica na memória deste processo."
note "Cole a Service API Key da Unipile (o campo é oculto). Enter em branco pula para o caminho pelo painel."
UNIPILE_API_KEY=$(limpar "$(ler_secreto "Chave de API da Unipile:")")
EDITADO=0
if [[ -n "$UNIPILE_API_KEY" ]]; then
  LISTA_JSON=$(mktemp)
  CODIGO=$(curl -sS -o "$LISTA_JSON" -w '%{http_code}' "$UNIPILE_API_BASE/v2/webhooks/endpoints" \
    -H "X-API-KEY: $UNIPILE_API_KEY" -H 'accept: application/json' 2>/dev/null) || CODIGO=000
  if [[ "$CODIGO" == 2* ]]; then
    LEITURA=$(endpoint_por_url "$LISTA_JSON" || true)
    ENDPOINT_ID=$(sed -n 1p <<<"$LEITURA"); EVENTOS_ATUAIS=$(sed -n 2p <<<"$LEITURA")
    if [[ -n "$ENDPOINT_ID" ]]; then
      note "Endpoint encontrado: $ENDPOINT_ID"
      note "Eventos hoje: ${EVENTOS_ATUAIS:-(nenhum lido)}"
      # A lista final: os eventos atuais mais os de e-mail, sem repetir.
      LISTA_EVENTOS=""
      while read -r evento; do
        [[ -n "$evento" ]] && LISTA_EVENTOS+="${LISTA_EVENTOS:+,}\"$evento\""
      done < <(tr ' ' '\n' <<<"$EVENTOS_ATUAIS ${EVENTOS_NOVOS[*]}" | awk 'NF && !v[$0]++')
      CORPO="{\"trigger_events\":[$LISTA_EVENTOS]}"
      for METODO in PATCH PUT; do
        CODIGO_EDICAO=$(curl -sS -o /dev/null -w '%{http_code}' -X "$METODO" "$UNIPILE_API_BASE/v2/webhooks/endpoints/$ENDPOINT_ID" \
          -H "X-API-KEY: $UNIPILE_API_KEY" -H 'accept: application/json' -H 'content-type: application/json' \
          -d "$CORPO" 2>/dev/null) || CODIGO_EDICAO=000
        if [[ "$CODIGO_EDICAO" == 2* ]]; then EDITADO=1; note "Editado por $METODO (HTTP $CODIGO_EDICAO)."; break; fi
      done
      if (( EDITADO )); then
        CODIGO=$(curl -sS -o "$LISTA_JSON" -w '%{http_code}' "$UNIPILE_API_BASE/v2/webhooks/endpoints" \
          -H "X-API-KEY: $UNIPILE_API_KEY" -H 'accept: application/json' 2>/dev/null) || true
        note "Eventos agora: $(endpoint_por_url "$LISTA_JSON" | sed -n 2p)"
      else
        warn "A API não aceitou a edição (último HTTP $CODIGO_EDICAO). Siga pelo painel."
      fi
    else
      warn "Nenhum endpoint com a URL $WEBHOOK_URL nesta conta Unipile. Se a conta é outra, rode scripts/wizard-unipile.sh."
    fi
  else
    warn "A Unipile respondeu HTTP $CODIGO à listagem de webhooks. Chave errada ou Account API Key (precisa ser Service)."
  fi
  rm -f "$LISTA_JSON"
  unset UNIPILE_API_KEY
fi
if (( ! EDITADO )); then
  open_url "$UNIPILE_PAINEL"
  step "No painel da Unipile, abra Webhooks e edite o endpoint com a URL:"
  note "  $WEBHOOK_URL"
  step "Acrescente os eventos email.new e email.new.bounce aos 7 de conta já marcados e salve."
  warn "Não crie um endpoint novo: ele viria com outro segredo e o webhook publicado recusaria as entregas."
  if confirm "Os dois eventos foram acrescentados no painel?"; then
    note "Certo."
  else
    SKIPPED+=("Webhook Endpoint da Unipile: acrescentar email.new e email.new.bounce a $WEBHOOK_URL")
  fi
fi
note "Avise o Renan: o endpoint é compartilhado com a frente de Conexões."
pause "Tecle Enter para seguir"

stage "O ciclo real de teste"
say "Agora o teste de ponta a ponta, com uma caixa de e-mail que não seja a da Conta remetente"
say "(althius.relacionamento@gmail.com), porque a resposta do próprio titular é eco, não resposta."
step "No Workspace operacional do app, cadastre uma Conta-alvo e um Contato com o e-mail dessa caixa."
step "Crie uma Sequência com um passo de E-mail para esse Contato e abra o detalhe."
step "No rodapé do passo, clique em \"Confirmar e enviar\". Deve aparecer \"Enviado em … para …\"."
step "Responda pela caixa de teste. Em até uns 10 s a Sequência fica \"Pausada\" e o painel"
say "  \"Respostas recebidas\" mostra assunto, corpo e anexos."
open_url "$PAINEL/functions/unipile-account-status/logs"
step "Nos logs do webhook, procure as linhas JSON: outcome \"echo\" para o seu envio (prova que o"
say "  cabeçalho X-Althius-Envio voltou) e outcome \"reply\" para a resposta."
note "A conferir neste primeiro ciclo: a forma da resposta de GET /threads/{id}, GET /emails/{id} e"
note "GET /email-senders da Unipile, usadas antes de um passo \"Re:\" (supabase/functions/README.md)."
note "O teste grátis da Unipile acaba por volta de 2026-10-03."
pause "Tecle Enter para encerrar"

finish
